<?php
namespace Tests\Feature;
use Tests\TestCase;use Tests\Concerns\MarketingEditingFixtures;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\{Queue,Http};use Illuminate\Support\Str;use App\Models\{User,MarketingAiRun};use App\Services\Marketing\{MarketingSemanticOptimization,MarketingSemanticEvidence,MarketingSemanticClient,MarketingSemanticCompiler};use App\Jobs\ProcessMarketingSemanticOptimization;
class MarketingSemanticOptimizationTest extends TestCase {
 use RefreshDatabase,MarketingEditingFixtures;
 public function test_semantic_action_fits_existing_mysql_varchar20_contract():void {$this->assertLessThanOrEqual(20,strlen(MarketingSemanticOptimization::ACTION));$this->assertNotSame('film_optimization',MarketingSemanticOptimization::ACTION);}
 private function source():array {Queue::fake();[$p,$f]=$this->editingFilm();$p->update(['brief'=>array_replace($p->brief,['source_confirmed'=>true,'facts_confirmed'=>true])]);$p->currentRevision->update(['context'=>array_replace($p->currentRevision->context,['brief'=>$p->brief])]);$this->actingAs(User::find($p->owner_id));return [$p,$f];}
 public function test_saved_answer_survives_compile_failure_and_recovery_never_calls_model():void {[$p,$f]=$this->source();$s=app(MarketingSemanticOptimization::class);$r=$s->start($p->id,$p->owner_id,$f->id,$f->output_sha256,(string)Str::uuid());$this->partialMock(MarketingSemanticEvidence::class)->shouldReceive('collect')->once()->andReturn(['samples'=>[],'references'=>[]]);$this->mock(MarketingSemanticClient::class)->shouldReceive('inspect')->once()->andReturn(['answer'=>['scenes'=>[]],'usage'=>['total_tokens'=>1],'model'=>'fixture','response_id'=>'fixture']);$this->mock(MarketingSemanticCompiler::class)->shouldReceive('compile')->once()->andThrow(new \RuntimeException('local compile fixture'));$s->process($r->id);$this->assertSame(['scenes'=>[]],$r->fresh()->usage['raw_answer']);$this->mock(MarketingSemanticCompiler::class)->shouldReceive('compile')->once()->andReturn(['applied'=>[],'skipped'=>[],'state'=>[],'provenance'=>[]]);$s->resumeCached($r->id);$this->assertSame('completed',$r->fresh()->status);$this->assertSame(1,$r->fresh()->usage['provider_attempts']);Http::assertNothingSent();}
 public function test_foreign_owner_cannot_start_semantic_and_changed_facts_invalidate_cache():void {[$p,$f]=$this->source();$s=app(MarketingSemanticOptimization::class);$r=$s->start($p->id,$p->owner_id,$f->id,$f->output_sha256,(string)Str::uuid());$foreign=User::factory()->create();try{$s->start($p->id,$foreign->id,$f->id,$f->output_sha256,(string)Str::uuid());$this->fail('foreign owner accepted');}catch(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface|\Illuminate\Database\Eloquent\ModelNotFoundException $e){$this->assertTrue(true);}$p->update(['brief'=>array_replace($p->brief,['facts'=>'changed'])]);$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface::class);$s->read($p->id,$p->owner_id,$f->id,$r->id);}
 public function test_legacy_cache_cannot_satisfy_semantic_and_uuid_duplicates_queue_once():void {[$p,$f]=$this->source();$legacy=MarketingAiRun::create(['project_id'=>$p->id,'action'=>'film_optimization','request_id'=>(string)Str::uuid(),'status'=>'completed','usage'=>['film_id'=>$f->id]]);$s=app(MarketingSemanticOptimization::class);$a=$s->start($p->id,$p->owner_id,$f->id,$f->output_sha256,(string)Str::uuid());$b=$s->start($p->id,$p->owner_id,$f->id,$f->output_sha256,(string)Str::uuid());$this->assertNotSame($legacy->id,$a->id);$this->assertSame($a->id,$b->id);Queue::assertPushed(ProcessMarketingSemanticOptimization::class,1);Http::assertNothingSent();}
 public function test_get_never_enqueues_and_wrong_owner_or_hash_is_rejected():void {[$p,$f]=$this->source();$s=app(MarketingSemanticOptimization::class);$this->assertNull($s->read($p->id,$p->owner_id,$f->id));Queue::assertNothingPushed();$this->expectException(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface::class);$s->start($p->id,$p->owner_id,$f->id,str_repeat('0',64),(string)Str::uuid());}
 public function test_unknown_request_is_claimed_once_and_is_never_retried():void {[$p,$f]=$this->source();$s=app(MarketingSemanticOptimization::class);$r=$s->start($p->id,$p->owner_id,$f->id,$f->output_sha256,(string)Str::uuid());$this->partialMock(MarketingSemanticEvidence::class)->shouldReceive('collect')->once()->andReturn(['samples'=>[],'references'=>[]]);$this->mock(MarketingSemanticClient::class)->shouldReceive('inspect')->once()->andThrow(new \RuntimeException('unknown fixture'));$s->process($r->id);$s->process($r->id);$this->assertSame('unknown',$r->fresh()->status);$this->assertSame(1,$r->fresh()->usage['provider_attempts']);$this->assertSame('failed',$s->present($r->fresh())['one_click']['status']);Http::assertNothingSent();}
 public function test_empty_validated_result_keeps_source_without_rendering():void {[$p,$f]=$this->source();$s=app(MarketingSemanticOptimization::class);$r=$s->start($p->id,$p->owner_id,$f->id,$f->output_sha256,(string)Str::uuid());$identity=app(MarketingSemanticEvidence::class)->identity($f);$this->partialMock(MarketingSemanticEvidence::class)->shouldReceive('collect')->once()->andReturn(['identity'=>$identity,'samples'=>[],'references'=>[]]);$this->mock(MarketingSemanticClient::class)->shouldReceive('inspect')->once()->andReturn(['answer'=>['scenes'=>[]],'usage'=>[],'model'=>'fixture','response_id'=>'fixture']);$this->mock(MarketingSemanticCompiler::class)->shouldReceive('compile')->once()->andReturn(['applied'=>[],'skipped'=>[],'state'=>[],'provenance'=>[]]);$s->process($r->id);$this->assertSame('completed',$r->fresh()->status);$this->assertSame('unchanged',$r->fresh()->usage['one_click']['status']);$this->assertDatabaseMissing('marketing_video_films',['result->ai_optimization->run_id'=>$r->id]);Http::assertNothingSent();}
}
